/**
 * TASK: Write the checks that decide whether a LeapRule is correct.
 *
 * The LeapRule contract:
 *   isLeapYear(year) is true when the year has 29 days in February: a year
 *   divisible by 4 is a leap year, EXCEPT a year divisible by 100, UNLESS it is
 *   also divisible by 400.
 *     2024 -> true, 2023 -> false, 1900 -> false, 2000 -> true
 *   A year outside 1..9999 is not a question the rule answers: the method must
 *   throw IllegalArgumentException for it.
 *
 * So this checker has to test two different kinds of behaviour. For a legal
 * year, a thrown exception is a failure. For an illegal year, NOT throwing is
 * the failure -- call the method, and if it returns normally the implementation
 * is broken.
 *
 * isCorrect(impl) returns true only when both kinds of behaviour are right.
 * The obvious years (2024, 2023) are agreed on by every broken rule here.
 */
interface LeapRule {
    /* Provided -- do not edit. */
    boolean isLeapYear(int year);
}

public class LeapRuleChecker {

    public static boolean isCorrect(LeapRule impl) {
        // TODO: check the century years that separate the rules, and check that an
        // out-of-range year throws IllegalArgumentException instead of answering.
        return true;
    }
}

