public class LeapRuleCheckerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static Object verdict(LeapRule impl) {
        try {
            return LeapRuleChecker.isCorrect(impl);
        } catch (Throwable crash) {
            return "isCorrect threw " + crash.getClass().getSimpleName();
        }
    }

    public static void main(String[] args) {
        check("accepts the correct implementation", true, verdict(new CorrectLeapRule()));
        check("accepts an equally correct implementation", true, verdict(new AlsoCorrectLeapRule()));
        check("rejects the divisible-by-four-only bug", false, verdict(new DivisibleByFourRule()));
        check("rejects the forgot-the-400-rule bug", false, verdict(new ForgetsFourHundredRule()));
        check("rejects the answers-instead-of-throwing bug", false, verdict(new SilentOnBadYearRule()));
        check("rejects the always-true stub", false, verdict(new AlwaysLeapRule()));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

class CorrectLeapRule implements LeapRule {
    public boolean isLeapYear(int year) {
        guard(year);
        if (year % 400 == 0) {
            return true;
        }
        if (year % 100 == 0) {
            return false;
        }
        return year % 4 == 0;
    }

    static void guard(int year) {
        if (year < 1 || year > 9999) {
            throw new IllegalArgumentException("year out of range: " + year);
        }
    }
}

class AlsoCorrectLeapRule implements LeapRule {
    public boolean isLeapYear(int year) {
        CorrectLeapRule.guard(year);
        return year % 4 == 0 && (year % 100 != 0 || year % 400 == 0);
    }
}

class DivisibleByFourRule implements LeapRule {
    public boolean isLeapYear(int year) {
        CorrectLeapRule.guard(year);
        return year % 4 == 0;
    }
}

class ForgetsFourHundredRule implements LeapRule {
    public boolean isLeapYear(int year) {
        CorrectLeapRule.guard(year);
        return year % 4 == 0 && year % 100 != 0;
    }
}

class SilentOnBadYearRule implements LeapRule {
    public boolean isLeapYear(int year) {
        if (year < 1 || year > 9999) {
            return false;
        }
        return year % 4 == 0 && (year % 100 != 0 || year % 400 == 0);
    }
}

class AlwaysLeapRule implements LeapRule {
    public boolean isLeapYear(int year) {
        CorrectLeapRule.guard(year);
        return true;
    }
}

